INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (1, 'วัดพระเชตุพนวิมลมังคลาราม (วัดโพธิ์)', 'กรุงเทพมหานคร', 'เขตพระนคร', 'แขวงพระบรมมหาราชวัง เขตพระนคร กรุงเทพมหานคร', 'ประวัติความเป็นมา
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (2, 'วัดอรุณราชวรารามราชวรมหาวิหาร (วัดอรุณ)', 'กรุงเทพมหานคร', 'เขตบางกอกใหญ่', '158 ถนนวังเดิม แขวงวัดอรุณ เขตบางกอกใหญ่ กรุงเทพมหานคร', 'ควย', NULL, 13.7438976, 100.4885137, 'assets/images/temple-watarun.jpg', NULL, 'ยอดนิยม', '2026-03-22 23:40:31') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (3, 'วัดพระศรีรัตนมหาธาตุวรมหาวิหาร (วัดใหญ่)', 'พิษณุโลก', 'เมืองพิษณุโลก', 'อ.เมือง จ.พิษณุโลก', NULL, NULL, 16.8235223, 100.2632084, 'assets/images/temple-watyai.jpg', NULL, 'แนะนำ', '2026-03-22 23:40:31') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (4, 'วัดพระศรีรัตนศาสดาราม (วัดพระแก้ว)', 'กรุงเทพมหานคร', 'เขตพระนคร', 'แขวงพระบรมมหาราชวัง เขตพระนคร กรุงเทพมหานคร', 'พระอารามหลวงในพระบรมมหาราชวัง สร้างขึ้นเมื่อ พ.ศ. 2325 ไม่มีพระสงฆ์จำพรรษา ประดิษฐาน "พระพุทธมหามณีรัตนปฏิมากร" (พระแก้วมรกต) สิ่งศักดิ์สิทธิ์สูงสุดคู่บ้านคู่เมืองไทย พร้อมสถาปัตยกรรมพระศรีรัตนเจดีย์ ปราสาทพระเทพบิดร และจิตรกรรมระเบียงคดรามเกียรติ์', NULL, 13.7514974, 100.4926592, 'uploads/temple_dfc9bca6c2c31002497795a84412a671.jpg', NULL, 'แนะนำ', '2026-09-12 00:33:56') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (5, 'วัดสมานรัตนาราม (พระพิฆเนศองค์ใหญ่)', 'ฉะเชิงเทรา', 'เมืองฉะเชิงเทรา', 'ต.บางแก้ว อ.เมืองฉะเชิงเทรา จ.ฉะเชิงเทรา', 'วัดริมแม่น้ำบางปะกง ประดิษฐาน "พระพิฆเนศปางนอนเสวยสุข" องค์สีชมพูขนาดใหญ่ที่สุดในไทย (สูง 16 เมตร ยาว 22 เมตร) ผู้คนนิยมมากระซิบขอพรที่หูหนูมุสิกะบริวารเพื่อสื่อคำอธิษฐาน', NULL, NULL, NULL, 'uploads/temple_15329cf02ae15f1fb09fa1be9e291e0b.jpg', NULL, 'ทั่วไป', '2026-09-12 00:33:56') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (6, 'วัดพระธาตุดอยสุเทพราชวรวิหาร', 'เชียงใหม่', 'เมืองเชียงใหม่', 'ต.สุเทพ อ.เมืองเชียงใหม่ จ.เชียงใหม่', 'พระธาตุเจดีย์ทรงเชียงแสนหุ้มทองจังโกสีทองสุกปลั่งบนยอดดอยสุเทพ บันไดนาค 306 ขั้น จุดชมวิวพาโนรามาของเมืองเชียงใหม่ และเป็นพระธาตุประจำปีเกิดของคนปีมะแม', NULL, 18.8050094, 98.9221843, 'uploads/temple_af13484c08705c745167a38ce589d901.jpg', NULL, 'ยอดนิยม', '2026-09-12 00:33:56') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (7, 'วัดร่องขุ่น (วัดขาว)', 'เชียงราย', 'เมืองเชียงราย', 'ต.ป่าอ้อดอนชัย อ.เมืองเชียงราย จ.เชียงราย', 'พุทธศิลป์ร่วมสมัยระดับโลกโดยอาจารย์เฉลิมชัย โฆษิตพิพัฒน์ พระอุโบสถสีขาวประดับกระจกเงิน สะพานข้ามวัฏสงสาร และภาพจิตรกรรมฝาผนังร่วมสมัยแฝงคติธรรม', NULL, NULL, NULL, 'uploads/temple_9b341dc786ad88f99fc14527971b517b.jpg', NULL, 'แนะนำ', '2026-09-12 00:33:56') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (8, 'วัดพระมหาธาตุวรมหาวิหาร', 'นครศรีธรรมราช', 'เมืองนครศรีธรรมราช', 'ต.ในเมือง อ.เมืองนครศรีธรรมราช จ.นครศรีธรรมราช', 'ศูนย์กลางพุทธศาสนาฝ่ายเถรวาทในแหลมมลายู โดดเด่นด้วย พระบรมธาตุเจดีย์ ยอดหุ้มทองคำแท้ ปรากฏการณ์ธรรมชาติ "พระธาตุไร้เงา" และรายล้อมด้วยเจดีย์บริวาร 158 องค์', NULL, NULL, NULL, 'uploads/temple_ebb5f2e8387dafb3d3b59c00754706eb.jpg', NULL, 'ยอดนิยม', '2026-09-12 00:33:56') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (9, 'วัดเจดีย์ (ไอ้ไข่)', 'นครศรีธรรมราช', 'สิชล', 'ต.ฉลอง อ.สิชล จ.นครศรีธรรมราช', 'วัดที่มีตำนานวิญญาณเด็กศักดิ์สิทธิ์ผู้ติดตามหลวงปู่ทวด โด่งดังด้วยรูปไม้แกะสลัก "ไอ้ไข่ วัดเจดีย์" กับวลี "ขอได้ไหว้รับ" ผู้คนหลั่งไหลมาขอพรโชคลาภและแก้บนด้วยประทัดและรูปปั้นไก่ชน', NULL, 8.9114065, 99.845372, 'uploads/temple_a02efb93d74e36ebdecdff0a891220d1.jpg', NULL, 'ยอดนิยม', '2026-09-12 00:33:56') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (10, 'วัดโสธรวรารามวรมหาวิหาร (วัดหลวงพ่อโสธร)', 'ฉะเชิงเทรา', 'เมืองฉะเชิงเทรา', 'ต.หน้าเมือง อ.เมืองฉะเชิงเทรา จ.ฉะเชิงเทรา', 'วัดโบราณริมแม่น้ำบางปะกง ประดิษฐาน "หลวงพ่อโสธร" พระพุทธรูปลอยน้ำศักดิ์สิทธิ์คู่บ้านคู่เมือง พระอุโบสถหลังใหม่สร้างด้วยหินอ่อนทรงจตุรมุขยอดมณฑปสูงสง่างาม', NULL, NULL, NULL, 'uploads/temple_3ccc4c04b7b832a522b0f7ae9472b445.jpg', NULL, 'แนะนำ', '2026-09-12 00:33:56') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (11, 'วัดเบญจมบพิตรดุสิตวนารามราชวรวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงดุสิต เขตดุสิต กรุงเทพมหานคร', '"วัดหินอ่อน" (The Marble Temple) พระอารามหลวงประจำรัชกาลที่ 5 สร้างด้วยหินอ่อนสีขาวคาร์ราราจากอิตาลีทั้งหลัง ออกแบบโดยสมเด็จฯ เจ้าฟ้ากรมพระยานริศรานุวัดติวงศ์ พระอุโบสถประดิษฐานพระพุทธชินราชจำลอง', NULL, 13.7661748, 100.5138073, 'uploads/temple_4f7a6337e48a2ef7e48779414284ebe3.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (12, 'วัดปากน้ำภาษีเจริญ', 'กรุงเทพมหานคร', NULL, 'แขวงปากคลองภาษีเจริญ เขตภาษีเจริญ กรุงเทพมหานคร', 'โด่งดังจากหลวงพ่อสด (พระมงคลเทพมุนี) ผู้ค้นพบวิชาธรรมกาย ประดิษฐาน "พระพุทธธรรมกายเทพมงคล" พระพุทธรูปทองสัมฤทธิ์ปางสมาธิสูง 69 เมตรริมคลอง และพระมหาเจดีย์มหารัชมงคลที่มีเจดีย์แก้วมรกตจำลอง', NULL, 13.7216719, 100.4704273, 'uploads/temple_8971fe8c882f49992ca8b4c8a412042f.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (13, 'วัดสระเกศราชวรมหาวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงบ้านบาตร เขตป้อมปราบศัตรูพ่าย กรุงเทพมหานคร', 'พระอารามหลวงสมัยอยุธยา โดดเด่นด้วย พระบรมบรรพต (ภูเขาทอง) ภูเขาจำลองสูง 77 เมตร บันไดวน 344 ขั้น ยอดบนสุดประดิษฐานพระบรมสารีริกธาตุจากอินเดีย พร้อมจุดชมวิวเมืองเก่ากรุงเทพฯ 360 องศา', NULL, 13.7533475, 100.507484, 'uploads/temple_9959aec7c07cd207086550ce9a62b621.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (14, 'วัดกัลยาณมิตรวรมหาวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงวัดกัลยาณ์ เขตธนบุรี กรุงเทพมหานคร', 'สร้างริมแม่น้ำเจ้าพระยาฝั่งธนบุรีในสมัยรัชกาลที่ 3 ประดิษฐาน "พระพุทธไตรรัตนนายก" (หลวงพ่อโต หรือ ซำปอกง) พระพุทธรูปปางมารวิชัยองค์ใหญ่ เป็นศูนย์รวมจิตใจชาวไทย-จีน นิยมขอพรเรื่องการค้าขายและความก้าวหน้า', NULL, 13.7400878, 100.4912378, 'uploads/temple_249a4a0247f443fcebd2b5d9a0172b80.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (15, 'วัดสุทัศนเทพวรารามราชวรมหาวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงวัดราชบพิธ เขตพระนคร กรุงเทพมหานคร', 'ตั้งอยู่หน้าเสาชิงช้า พระวิหารหลวงขนาดใหญ่ที่สุดในไทย ประดิษฐาน "พระศรีศากยมุนี" พระหล่อสำริดโบราณจากสุโขทัย บานประตูไม้แกะสลักลึก 3 มิติ ฝีพระหัตถ์รัชกาลที่ 2', NULL, 13.7502791, 100.5009474, 'uploads/temple_c7dea26e5054c5ca7e57108fa07c2ecc.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (16, 'วัดปทุมวนารามราชวรวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงปทุมวัน เขตปทุมวัน กรุงเทพมหานคร', 'วัดบรรยากาศสงบใจกลางย่านสยามสแควร์ สร้างในสมัยรัชกาลที่ 4 ประดิษฐานพระพุทธรูปโบราณจากเวียงจันทน์ ได้แก่ "พระเสริม" และ "พระสายน์" พร้อมจิตรกรรมฝาผนังลวดลายบัวอันเป็นเอกลักษณ์', NULL, 13.7467959, 100.5368818, 'uploads/temple_dffcd7532a3b1e7984199143dfbc554f.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (17, 'วัดอินทรวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงบางขุนพรหม เขตพระนคร กรุงเทพมหานคร', 'ประดิษฐาน "หลวงพ่อโต" (พระพุทธศรีอริยเมตไตรย) พระพุทธรูปยืนอุ้มบาตรองค์ใหญ่สูง 32 เมตร ริเริ่มสร้างโดยสมเด็จพระพุฒาจารย์ (โต พรหมรังสี) และมีบ่อน้ำพระพุทธมนต์ศักดิ์สิทธิ์รวมน้ำมนต์จากวัดทั่วประเทศ', NULL, 13.7668064, 100.5029823, 'uploads/temple_238249d4986da8061f108506c6086c37.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (18, 'วัดยานนาวา', 'กรุงเทพมหานคร', NULL, 'แขวงยานนาวา เขตสาทร กรุงเทพมหานคร', 'เดิมชื่อวัดคอกควาย รัชกาลที่ 3 ทรงบูรณะและสร้าง สำเภาพระเจดีย์ อาคารฐานรูปเรือสำเภาจีนโบราณขนาดใหญ่ เพื่อให้คนรุ่นหลังได้เห็นรูปแบบเรือสำเภาค้าขายโบราณที่กำลังจะสูญหาย', NULL, 13.7173522, 100.5135219, 'uploads/temple_00886575e19ebb5fb361e2b43d175103.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (19, 'วัดพระปฐมเจดีย์ราชวรมหาวิหาร', 'นครปฐม', NULL, 'ต.พระปฐมเจดีย์ อ.เมืองนครปฐม จ.นครปฐม', 'บราณสถานยุคสุวรรณภูมิ-ทวารวดี รัชกาลที่ 4 โปรดให้สร้างพระเจดีย์ทรงระฆังคว่ำสีทองครอบองค์เดิมไว้ เป็น พระสถูปเจดีย์ที่สูงที่สุดในประเทศไทย (สูง 120.45 เมตร) ประดิษฐาน "พระร่วงโรจนฤทธิ์"', NULL, 13.8205876, 100.0598607, 'uploads/temple_92ee4d2437b3f915105e60bb3cfb6eb5.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (20, 'วัดใหญ่ชัยมงคล', 'พระนครศรีอยุธยา', NULL, 'ต.คลองสวนพลู อ.พระนครศรีอยุธยา จ.พระนครศรีอยุธยา', 'เดิมชื่อวัดป่าแก้ว สมเด็จพระนเรศวรมหาราชโปรดให้สร้าง พระเจดีย์ชัยมงคล ทรงระฆังคว่ำขนาดใหญ่เพื่อเฉลิมฉลองชัยชนะในสงครามยุทธหัตถี รายล้อมด้วยพระพุทธรูปปูนปั้นปางมารวิชัยรอบระเบียงคด', NULL, NULL, NULL, 'uploads/temple_daffd0c810a00867bf1f6db3d6b30715.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (21, 'วัดหน้าพระเมรุราชิการาม', 'พระนครศรีอยุธยา', NULL, 'ต.ท่าวาสุกรี อ.พระนครศรีอยุธยา จ.พระนครศรีอยุธยา', 'วัดเดียวในกรุงศรีอยุธยาที่ไม่ถูกพม่าเผาทำลาย ในคราวเสียกรุงครั้งที่ 2 พระอุโบสถยังคงศิลปกรรมอยุธยาแท้ หน้าบันไม้แกะสลักนารายณ์ทรงสุบรรณ ประดิษฐาน "พระพุทธนิมิตวิชิตมารโมลีศรีสรรเพชญบรมไตรโลกนาถ" พระพุทธรูปทรงเครื่องกษัตริย์ที่งดงามสมบูรณ์ที่สุด', NULL, 14.3628327, 100.5588113, 'uploads/temple_70527833ccf1c1226adc80aa25aded6e.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (22, 'วัดไชยวัฒนาราม', 'พระนครศรีอยุธยา', NULL, 'ต.บ้านป้อม อ.พระนครศรีอยุธยา จ.พระนครศรีอยุธยา', 'สร้างขึ้นในปี พ.ศ. 2173 โดยสมเด็จพระเจ้าปราสาททอง ริมแม่น้ำเจ้าพระยา โดดเด่นด้วยพระปรางค์ประธานทรงขอมจำลองคติจักรวาลวิทยาเขาพระสุเมรุ ล้อมรอบด้วยปรางค์ทิศและเมรุทิศ 8 ทิศ เป็นโบราณสถานที่สมบูรณ์และงดงามที่สุดแห่งหนึ่งของอยุธยา0', NULL, NULL, NULL, 'uploads/temple_9823ff24ea70578b0ded43ae3fa439a6.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (23, 'วัดพระธาตุช่อแฮ พระอารามหลวง', 'แพร่', NULL, 'ต.ช่อแฮ อ.เมืองแพร่ จ.แพร่', 'พระธาตุเจดีย์แปดเหลี่ยมย่อมุมสิบสอง ศิลปะเชียงแสน หุ้มด้วยทองจังโก เป็นพระธาตุประจำปีเกิดของคนปีขาล (ปีเสือ) ภายในประดิษฐานพระเกศาธาตุและพระบรมสารีริกธาตุพระศอกซ้าย', NULL, NULL, NULL, 'uploads/temple_5e3bdd2964699f8e5f3f1e1de6c9821b.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (24, 'วัดพระธาตุแช่แห้ง พระอารามหลวง', 'น่าน', NULL, 'ต.ม่วงตึ๊ด อ.ภูเพียง จ.น่าน', 'สร้างขึ้นเมื่อ พ.ศ. 1896 องค์พระธาตุสีทองอร่ามบนยอดเนินเขาสูง 55 เมตร บรรจุพระบรมสารีริกธาตุ เป็นพระธาตุประจำปีเกิดของคนปีกระต่าย (ปีเถาะ) พร้อมบันไดพญานาคเลื้อยขึ้นสู่วิหารหลวง', NULL, NULL, NULL, 'uploads/temple_361b5a5207d9d45d0063cd86ed7757bd.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (25, 'วัดพระธาตุลำปางหลวง', 'ลำปาง', NULL, 'ต.ลำปางหลวง อ.เกาะคา จ.ลำปาง', 'วัดไม้โบราณที่สมบูรณ์ที่สุดแห่งหนึ่งในล้านนา องค์พระธาตุเจดีย์หุ้มทองจังโกเป็นพระธาตุประจำปีฉลู วิหารหลวงเปิดโล่งไม่มีฝาผนังตามขนบโบราณ และมีปรากฏการณ์ "เงาพระธาตุกลับหัว" ผ่านรูเข็มในมณฑป', NULL, 18.2168322, 99.3886802, 'uploads/temple_3fc86de449adfc9c272bd2f3eb1c46fc.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (26, 'วัดพระแก้ว (วัดพระศรีรัตนศาสดาราม)', 'กรุงเทพมหานคร', NULL, 'แขวงพระบรมมหาราชวัง เขตพระนคร กรุงเทพมหานคร', 'สร้างขึ้นพร้อมพระบรมมหาราชวังเมื่อ พ.ศ. 2325 ไม่มีพระสงฆ์จำพรรษา ประดิษฐาน "พระพุทธมหามณีรัตนปฏิมากร" (พระแก้วมรกต) สิ่งศักดิ์สิทธิ์คู่บ้านคู่เมือง พร้อมปราสาทพระเทพบิดร พระศรีรัตนเจดีย์ และจิตรกรรมรามเกียรติ์รอบระเบียงคด', NULL, 13.7514974, 100.4926592, 'uploads/temple_1a6fc2544fa649a42a9f8d986af92032.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (27, 'วัดซ้ำ', 'กรุงเทพมหานคร', NULL, '', '', NULL, NULL, NULL, NULL, NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (28, 'วัดบวรนิเวศราชวรวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงบวรนิเวศ เขตพระนคร กรุงเทพมหานคร', 'พระอารามเอกแห่งธรรมยุติกนิกาย ที่ประทับของพระมหากษัตริย์ไทยเมื่อครั้งทรงผนวชหลายพระองค์ ประดิษฐาน "พระพุทธชินสีห์" และ "พระสุวรรณเขต" (หลวงพ่อโต) คู่กัน พร้อมจิตรกรรมฝาผนังฝีมือขรัวอินโข่ง', NULL, 13.7597528, 100.5006424, 'uploads/temple_9cff7124c2c8082e0157a2fa18c02a5e.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (29, 'วัดราชบพิธสถิตมหาสีมารามราชวรวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงวัดราชบพิธ เขตพระนคร กรุงเทพมหานคร', 'พระอารามหลวงประจำรัชกาลที่ 5 ภายนอกประดับกระเบื้องเคลือบเบญจรงค์ทำมือลายไทยทั้งหลัง แต่ ภายในอุโบสถตกแต่งสถาปัตยกรรมกอทิกแบบตะวันตก ปัจจุบันเป็นที่ประทับของสมเด็จพระสังฆราช', NULL, 13.7490287, 100.4971777, 'uploads/temple_f21079c789049fb5f1676e905341c7ca.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (30, 'วัดราชประดิษฐสถิตมหาสีมารามราชวรวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงพระบรมมหาราชวัง เขตพระนคร กรุงเทพมหานคร', 'รัชกาลที่ 4 โปรดเกล้าฯ ให้สร้างขึ้นในปี พ.ศ. 2407 เพื่อเป็นวัดประจำคณะสงฆ์ธรรมยุต พระวิหารหลวงสร้างและบุด้วย หินอ่อนสีเทาทั้งหลัง ภายในมีภาพจิตรกรรมสุริยุปราคาเต็มดวงที่หว้ากอ', NULL, 13.7496598, 100.4956194, 'uploads/temple_b3f95d423ecde1d044ec5c222ca6ab1a.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (31, 'วัดไตรมิตรวิทยารามวรวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงตลาดน้อย เขตสัมพันธวงศ์ กรุงเทพมหานคร', 'เดิมชื่อวัดสามจีน พระมหามณฑปประดิษฐาน "พระพุทธมหาสุวรรณปฏิมากร" พระพุทธรูปทองคำแท้ขนาดใหญ่ที่สุดในโลก (น้ำหนักทองคำ 5.5 ตัน) ซึ่งเคยพอกปูนพรางตาไว้ตั้งแต่สมัยอยุธยา', NULL, 13.7379989, 100.5136529, 'uploads/temple_cfb7750db239f7dfd0c8acd314b8aa89.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (32, 'วัดมังกรกมลาวาส', 'กรุงเทพมหานคร', NULL, 'แขวงป้อมปราบ เขตป้อมปราบศัตรูพ่าย กรุงเทพมหานคร', 'สร้างขึ้นในปี พ.ศ. 2414 ในสมัยรัชกาลที่ 5 สถาปัตยกรรมแบบพระราชวังจีนแต้จิ๋ว เป็นศูนย์กลางการไหว้แก้ชง สะเดาะเคราะห์ต่อดวงชะตา และประดิษฐานเทพเจ้าไท้ส่วยเอี๊ยที่สำคัญที่สุดในเยาวราช', NULL, 13.7435379, 100.5095416, 'uploads/temple_7ae4733c5edb3fe80140937acc13ca65.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (33, 'วัดจักรวรรดิราชาวาสวรมหาวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงจักรวรรดิ เขตสัมพันธวงศ์ กรุงเทพมหานคร', 'วัดโบราณสมัยอยุธยา บูรณะโดยเจ้าพระยาบดินทรเดชา (สิงห์ สิงหเสนี) มีชื่อเสียงเรื่องบ่อเลี้ยงจระเข้โบราณตามตำนาน "ไอ้บอดวัดสามปลื้ม" พร้อมพระปรางค์ใหญ่และมณฑปพระพุทธฉายจำลอง', NULL, NULL, NULL, 'uploads/temple_7ab98c39017c69c91a28fc0574ad9ded.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (34, 'วัดระฆังโฆสิตารามวรมหาวิหาร', 'กรุงเทพมหานคร', NULL, 'แขวงศิริราช เขตบางกอกน้อย กรุงเทพมหานคร', 'เดิมชื่อวัดบางหว้าใหญ่ รัชกาลที่ 1 ทรงบูรณะหลังขุดพบระฆังโบราณเสียงดังกังวาน เป็นสำนักจำพรรษาของ สมเด็จพระพุฒาจารย์ (โต พรหมรังสี) ต้นกำเนิดบทสวดคาถาชินบัญชร และมีหอพระไตรปิฎกเรือนไทยไม้สัก 3 หลังแฝด', NULL, 13.7525748, 100.4856438, 'uploads/temple_ca60b6eec3e96dd3c1363e9790f85ade.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (35, 'วัดพระศรีรัตนมหาธาตุวรมหาวิหาร', 'พิษณุโลก', NULL, 'ต.ในเมือง อ.เมืองพิษณุโลก จ.พิษณุโลก', 'วัดริมแม่น้ำน่าน สันนิษฐานว่าสร้างขึ้นในสมัยพญาลิไท (ราว พ.ศ. 1900) ประดิษฐาน "พระพุทธชินราช" พระพุทธรูปที่ได้รับการยกย่องว่างดงามที่สุดในไทย พระปรางค์ประธานบรรจุพระบรมสารีริกธาตุ บานประตูวิหารประดับมุกสมัยอยุธยาตอนปลาย และพระอัฏฐารสยืนสูง 18 ศอก', NULL, 16.8235223, 100.2632084, 'uploads/temple_65dcc16ab8aa5039e0f4d5051da3e2a0.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (36, 'วัดพระพุทธชินราช', 'พิษณุโลก', NULL, 'ต.ในเมือง อ.เมืองพิษณุโลก จ.พิษณุโลก', 'สร้างขึ้นในสมัยพญาลิไทแห่งสุโขทัย (พ.ศ. 1900) ประดิษฐาน "พระพุทธชินราช" พระพุทธรูปที่ได้รับการยกย่องว่างดงามที่สุดในไทย บานประตูมุกสมัยอยุธยา พระอัฏฐารสยืนสูง 18 ศอก และพระปรางค์ประธานบรรจุพระบรมสารีริกธาตุ', NULL, NULL, NULL, 'uploads/temple_181d3707b1ef31c3c21e51c273531aff.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (37, 'วัดพระธาตุดอยสุเทพราชวรวิหาร', 'เชียงใหม่', NULL, 'ต.สุเทพ อ.เมืองเชียงใหม่ จ.เชียงใหม่', 'สถาปนาในสมัยพระเจ้ากือนา (พ.ศ. 1927) โดยเสี่ยงทายช้างมงคลอัญเชิญพระบรมสารีริกธาตุขึ้นสู่ยอดดอย เจดีย์ทรงเชียงแสนหุ้มทองจังโกสีทองสุกปลั่ง บันไดนาค 306 ขั้น และเป็นพระธาตุประจำปีเกิดของคนปีมะแม', NULL, 18.8050094, 98.9221843, 'uploads/temple_d6c1bd722e27a188c1c47ccad0abc1e8.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (38, 'วัดเจดีย์หลวงวรวิหาร', 'เชียงใหม่', NULL, 'ต.พระสิงห์ อ.เมืองเชียงใหม่ จ.เชียงใหม่', 'ก่อตั้งในสมัยพญาแสนเมืองมา (พ.ศ. 1934) พระมหาเจดีย์หลวงก่ออิฐโบราณขนาดมหึมาที่เคยประดิษฐานพระแก้วมรกตนานกว่า 80 ปี และเป็นที่ตั้งของ "เสาอินทขีล" (เสาหลักเมืองเชียงใหม่)', NULL, 18.7871427, 98.986784, 'uploads/temple_c696cf6cf5aabcc63292b636773b2946.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (39, 'วัดพระสิงห์วรมหาวิหาร', 'เชียงใหม่', NULL, 'ต.พระสิงห์ อ.เมืองเชียงใหม่ จ.เชียงใหม่', 'สร้างเมื่อปี พ.ศ. 1888 โดยพญาผายู พระวิหารลายคำประดิษฐาน "พระพุทธสิหิงค์" (พระสิงห์) พระพุทธรูปคู่บ้านคู่เมืองเชียงใหม่ พร้อมจิตรกรรมฝาผนังลายทองรดน้ำ และเป็นพระธาตุประจำปีมะโรง', NULL, NULL, NULL, 'uploads/temple_7472ed3ef538782fc995fed063a3101a.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (40, 'วัดสวนดอก', 'เชียงใหม่', NULL, 'ต.สุเทพ อ.เมืองเชียงใหม่ จ.เชียงใหม่', 'สร้างขึ้นเมื่อปี พ.ศ. 1914 ในเขตอุทยานสวนดอกไม้เดิมสมัยพญากือนา โดดเด่นด้วยพระเจดีย์ประธานทรงระฆังสีทองบรรจุพระบรมสารีริกธาตุ และ กู่เจ้านายฝ่ายเหนือ กลุ่มเจดีย์สีขาวบรรจุอัฐิของเจ้านายราชตระกูล ณ เชียงใหม่', NULL, 18.787884, 98.9673564, 'uploads/temple_680170fe53feb5b9e2abfbc69580ed68.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (41, 'วัดร่องขุ่น', 'เชียงราย', NULL, 'ต.ป่าอ้อดอนชัย อ.เมืองเชียงราย จ.เชียงราย', 'ริเริ่มสร้างโดย ศาสตรเมธี ดร.เฉลิมชัย โฆษิตพิพัฒน์ ศิลปินแห่งชาติ พระอุโบสถสีขาวบริสุทธิ์ประดับกระจกเงินระยิบระยับ สะพานข้ามวัฏสงสาร และภาพจิตรกรรมฝาผนังร่วมสมัยแฝงปรัชญาธรรมหลุดพ้น', NULL, NULL, NULL, 'uploads/temple_580eb87a186be64477db25c40e716caf.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (42, 'วัดร่องเสือเต้น', 'เชียงราย', NULL, 'ต.ริมกก อ.เมืองเชียงราย จ.เชียงราย', 'สร้างสรรค์โดย นายพุทธา กาบแก้ว (สล่านก) ศิษย์อาจารย์เฉลิมชัย โดดเด่นด้วยสถาปัตยกรรม วิหารสีน้ำเงินครามตัดทอง พญานาคลวดลายอ่อนช้อย และพระประธานสีขาวมุกสะท้อนแสงไฟตระการตา', NULL, 19.923357, 99.8417552, 'uploads/temple_7db407e0593d620a6788bf3d58fc7a02.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (43, 'วัดพระธาตุหริภุญชัยวรมหาวิหาร', 'ลำพูน', NULL, 'ต.ในเมือง อ.เมืองลำพูน จ.ลำพูน', 'ศูนย์กลางอาณาจักรหริภุญชัย สร้างขึ้นราว พ.ศ. 1440 องค์พระบรมธาตุหริภุญชัยหุ้มทองจังโกสีทองอร่าม สูง 46 เมตร เป็นพระธาตุประจำปีเกิดของคนปีระกา (ปีไก่) ภายในมีสุวรรณเจดีย์และกังสดาลยักษ์', NULL, 18.5773757, 99.0078238, 'uploads/temple_713a02b19186ba18d90e03d1829a67f3.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (44, 'วัดภูมินทร์', 'น่าน', NULL, 'ต.ในเวียง อ.เมืองน่าน จ.น่าน', 'สร้างเมื่อปี พ.ศ. 2139 โดดเด่นด้วย อุโบสถจัตุรมุขหลังเดียวในไทย ฐานรองรับด้วยพญานาคคู่สะดุ้ง และภาพจิตรกรรมฝาผนังไทลื้ออันเลื่องชื่อ "ปู่ม่านย่าม่าน กระซิบรักบันลือโลก" ฝีมือหนานบัวผัน', NULL, 18.7742425, 100.7716392, 'uploads/temple_ba7556048636661d633106cb183047e8.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (45, 'วัดป่าภูก้อน', 'อุดรธานี', NULL, 'ต.บ้านก้อง อ.นายูง จ.อุดรธานี', 'วิหารยอดมณฑปหลังคาสีฟ้าเทอร์ควอยซ์บนยอดเขาสูงในเขตป่าสงวนแห่งชาติ ภายในประดิษฐาน "พระพุทธไสยาสน์โลกนาถศาสดามหามุนี" พระนอนหินอ่อนสีขาวจากอิตาลียาว 20 เมตร ท่ามกลางธรรมชาติทะเลหมอก', NULL, 17.9226271, 102.1183172, 'uploads/temple_3704150d56d304bf78207486d2c87739.jpg', NULL, 'แนะนำ', '2026-10-09 16:09:41') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (46, 'วัดพระธาตุพนมวรมหาวิหาร', 'นครพนม', NULL, 'ต.ธาตุพนม อ.ธาตุพนม จ.นครพนม', 'พระธาตุศักดิ์สิทธิ์คู่สองฝั่งโขง สร้างขึ้นราว พ.ศ. 8 บรรจุพระอุรังคธาตุ องค์พระธาตุทรงสี่เหลี่ยมหุ้มทองคำแท้ที่ยอดฉัตร เป็นพระธาตุประจำปีเกิดของคนปีวอก และพระธาตุประจำวันเกิดของผู้ที่เกิดวันอาทิตย์', NULL, NULL, NULL, 'uploads/temple_6efa7885f75eba7e569103c2e24d338d.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (47, 'วัดเทพพิทักษ์ปุณณาราม', 'นครราชสีมา', NULL, 'ต.กลางดง อ.ปากช่อง จ.นครราชสีมา', 'สร้างขึ้นโดยหลวงปู่เจี๊ยะ จุนโท ศิษย์หลวงปู่มั่น ประดิษฐาน "พระพุทธสกลสีมามงคล" (หลวงพ่อขาว) พระพุทธรูปปางประทานพรสีขาวขนาดใหญ่บนไหล่เขาสูง 56 เมตร บันไดขึ้นสู่ยอดเขา 1,250 ขั้น เท่ากับจำนวนพระอรหันต์ในวันมาฆบูชา', NULL, NULL, NULL, 'uploads/temple_d92cd0b39283db6ea5fd01ef702c1163.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (48, 'วัดกลางมิ่งเมือง', 'ร้อยเอ็ด', NULL, 'ต.ในเมือง อ.เมืองร้อยเอ็ด จ.ร้อยเอ็ด', 'พระอารามหลวงโบราณบนเนินดินสูง ในอดีตเคยใช้เป็นสถานที่ประกอบพิธีถือน้ำพระพิพัฒน์สัตยา ฝาผนังรอบอุโบสถมีภาพจิตรกรรมฝาผนังอีสาน (ฮูปแต้ม) บอกเล่าพุทธประวัติและวิถีชีวิตพื้นบ้าน', NULL, 16.0617203, 103.6544369, 'uploads/temple_ab8b51bf084077f9fa2f1a7be176834f.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (49, 'วัดพระนารายณ์มหาราชวรวิหาร', 'นครราชสีมา', NULL, 'ต.ในเมือง อ.เมืองนครราชสีมา จ.นครราชสีมา', 'เดิมชื่อวัดกลาง สมเด็จพระนารายณ์มหาราชโปรดเกล้าฯ ให้สร้างขึ้น มีพระอุโบสถกลางน้ำ และเทวรูปพระนารายณ์หินทรายสลักสี่กร ศิลปะลพบุรี-ขอมโบราณ สะท้อนประวัติศาสตร์การเปลี่ยนผ่านจากศาสนาพราหมณ์สู่พุทธ', NULL, NULL, NULL, 'uploads/temple_1075acd6bf54bcfbb4bfb298a626a9f1.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (50, 'วัดบึง', 'นครราชสีมา', NULL, 'ต.ในเมือง อ.เมืองนครราชสีมา จ.นครราชสีมา', 'สร้างขึ้นในสมัยสมเด็จพระนารายณ์มหาราช (พ.ศ. 2220) พร้อมกำแพงเมืองโคราช พระอุโบสถศิลปะอยุธยาตอนปลายฐานสำเภาแอ่นโค้ง ภายในประดิษฐาน "หลวงพ่อโตอู่ทอง" พระพุทธรูปปางมารวิชัยโบราณ', NULL, 14.9738488, 102.1000958, 'uploads/temple_cee96e589a3621b97ec9be2abd7cc427.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (51, 'วัดหนองป่าพง', 'อุบลราชธานี', NULL, 'ต.โนนผึ้ง อ.วารินชำราบ จ.อุบลราชธานี', 'สำนักสงฆ์สายวัดป่าต้นแบบ ก่อตั้งโดย หลวงปู่ชา สุภทฺโท ซึ่งมีสาขาขยายไปทั่วโลก เน้นความเรียบง่ายตามพระธรรมวินัย ภายในมี เจดีย์พระโพธิญาณสีทอง บรรจุอัฐิธาตุของหลวงปู่ชา', NULL, 15.1597777, 104.8305666, 'uploads/temple_a5c78f51c145f6cfd62dee2fded8a3ed.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (52, 'วัดเขาพระอังคาร', 'บุรีรัมย์', NULL, 'ต.เจริญสุข อ.เฉลิมพระเกียรติ จ.บุรีรัมย์', 'พุทธสถานบนยอดภูเขาไฟที่ดับสนิทแล้ว โดดเด่นด้วยสถาปัตยกรรมพระอุโบสถประยุกต์ศิลปะขอมโบราณ รายล้อมด้วยพระพุทธรูปปูนปั้นสีศิลาแลงนับร้อยองค์ และใบเสมาหินทรายยุคทวารวดีสลักภาพพุทธประวัติ', NULL, NULL, NULL, 'uploads/temple_fef3b72cb6b9bcbf1b0f089709bc732f.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (53, 'วัดกลางกาฬสินธุ์', 'กาฬสินธุ์', NULL, 'ต.กาฬสินธุ์ อ.เมืองกาฬสินธุ์ จ.กาฬสินธุ์', 'พระอารามหลวงแห่งแรกของจังหวัดกาฬสินธุ์ สร้างเมื่อ พ.ศ. 2389 เป็นที่ประดิษฐาน "หลวงพ่อองค์ดำ" (พระพุทธสัมฤทธิ์นิรโรคันตราย) พระพุทธรูปหล่อสำริดสีดำศิลปะล้านช้าง พระคู่บ้านคู่เมืองที่มีพิธีแห่สรงน้ำขอฝน', NULL, NULL, NULL, 'uploads/temple_21b7bb62ae19a2c134fc9870f478286c.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (54, 'วัดหินหมากเป้ง', 'หนองคาย', NULL, 'ต.พระพุทธบาท อ.ศรีเชียงใหม่ จ.หนองคาย', 'สำนักปฏิบัติธรรมริมฝั่งแม่น้ำโขง ก่อตั้งโดย หลวงปู่เทสก์ เทสรังสี พระมหาเถระสายวิปัสสนากรรมฐาน ภายในมีเจดีย์พิพิธภัณฑ์อัฐิบริขารของหลวงปู่เทสก์ ท่ามกลางธรรมชาติร่มรื่นและโขดหินริมน้ำโขง', NULL, 17.9824608, 102.4260854, 'uploads/temple_f72f0426116a82c4a665dcc1875a8eff.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (55, 'วัดทุ่งศรีเมือง', 'อุบลราชธานี', NULL, 'ต.ในเมือง อ.เมืองอุบลราชธานี จ.อุบลราชธานี', 'สร้างขึ้นในสมัยรัชกาลที่ 3 โดดเด่นด้วย หอพระไตรปิฎกไม้สักโบราณกลางสระน้ำ ศิลปะผสมผสานไทย ลาว และพม่า ยกเสาสูงเพื่อกันปลวกแมลง และมีหอพระพุทธบาทที่มีภาพจิตรกรรมฝาผนังล้านช้างดั้งเดิม', NULL, 15.230304, 104.8609127, 'uploads/temple_dff65918b4e6dd77862f8e5c28c79000.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (56, 'วัดเจติยาคีรีวิหาร (วัดภูทอก)', 'บึงกาฬ', NULL, 'ต.นาแสง อ.ศรีวิไล จ.บึงกาฬ', 'ก่อตั้งโดยพระอาจารย์จวน กุลเชฏโฐ ศิษย์หลวงปู่มั่น โดดเด่นด้วย สะพานไม้เวียนวนรอบหน้าผาสูงชัน 7 ชั้น ที่สร้างขึ้นด้วยแรงศรัทธาโดยไม่ใช้เครื่องจักรกลหนัก เพื่อเป็นปริศนาธรรมสู่การหลุดพ้น', NULL, 18.131798, 103.8806629, 'uploads/temple_12b443dc8a13ca22e74ec326497e6546.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (57, 'วัดธาตุหนองแวง', 'ขอนแก่น', NULL, 'ต.ในเมือง อ.เมืองขอนแก่น จ.ขอนแก่น', 'ตั้งอยู่ริมบึงแก่นนคร โดดเด่นด้วย "พระมหาธาตุแก่นนคร" (มหาเจดีย์ 9 ชั้น) สีทองอร่าม สูง 80 เมตร จัดแสดงพุทธประวัติ พระไตรปิฎก และชั้นบนสุดเป็นจุดชมวิวเมืองขอนแก่น 360 องศา', NULL, NULL, NULL, 'uploads/temple_166d27354e0e5f926af316a2821f01af.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (58, 'วัดมหาวนาราม', 'อุบลราชธานี', NULL, 'ต.ในเมือง อ.เมืองอุบลราชธานี จ.อุบลราชธานี', 'สร้างขึ้นเมื่อปี พ.ศ. 2350 โดยเจ้าคำผง เจ้าเมืองอุบลฯ คนแรก เพื่อเป็นวัดป่าสำหรับพระสายวิปัสสนา เป็นที่ประดิษฐาน "พระเจ้าใหญ่อินทร์แปลง" พระพุทธรูปศักดิ์สิทธิ์ศิลปะล้านช้างคู่บ้านคู่เมือง', NULL, 15.2347658, 104.8633853, 'uploads/temple_be9c02958f9e37b967b621dee260bf6e.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (59, 'วัดสุปัฏนารามวรวิหาร', 'อุบลราชธานี', NULL, 'ต.ในเมือง อ.เมืองอุบลราชธานี จ.อุบลราชธานี', 'พระอารามหลวงแห่งแรกของอุบลฯ และวัดธรรมยุตแห่งแรกในภาคอีสาน สร้างขึ้นสมัยรัชกาลที่ 4 โดดเด่นด้วย พระอุโบสถผสมผสาน 3 วัฒนธรรม (หลังคาไทย เสาและซุ้มโค้งแบบตะวันตก ฐานบัวแบบจีน) ริมฝั่งแม่น้ำมูล', NULL, 15.2254431, 104.8529454, 'uploads/temple_a7975d9b55c61ded2ef82334128e75ec.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (60, 'วัดพระธาตุเชิงชุมวรวิหาร', 'สกลนคร', NULL, 'ต.ธาตุเชิงชุม อ.เมืองสกลนคร จ.สกลนคร', 'ปูชนียสถานคู่บ้านคู่เมืองสกลนคร องค์พระธาตุสีขาวทรงสี่เหลี่ยม ยอดฉัตรทองคำแท้ สร้างครอบรอยพระพุทธบาทของพระพุทธเจ้า 4 พระองค์ ด้านหลังมีวิหารประดิษฐาน "หลวงพ่อพระองค์แสน"', NULL, 17.1646783, 104.1534594, 'uploads/temple_011f1eafff0f33a29c861aba6cde5b34.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (61, 'วัดถ้ำเขาน้อย', 'กาญจนบุรี', NULL, 'ต.ม่วงชุม อ.ท่าม่วง จ.กาญจนบุรี', 'วัดฝ่ายมหายาน (อนัมนิกาย) สายเวียดนาม ก่อตั้งเมื่อ พ.ศ. 2426 เคียงข้างวัดถ้ำเสือ โดดเด่นด้วยสถาปัตยกรรม เก๋งจีนโบราณแปดเหลี่ยมหลายชั้น (เก๋งจีนหมื่นพุทธ) และซุ้มประตูมังกร', NULL, 13.9531087, 99.6054349, 'uploads/temple_2a89667066743d91d3538b72244a4cee.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (62, 'วัดหินแท่นลำภาชี', 'กาญจนบุรี', NULL, 'ต.หนองไผ่ อ.ด่านมะขามเตี้ย จ.กาญจนบุรี', 'โด่งดังด้วย พระอุโบสถแก้วสีขาวบริสุทธิ์สร้างประดิษฐานอยู่บนฐานเรือสุพรรณหงส์ขนาดยักษ์ ด้านหน้ามีรูปหล่อท้าวเวสสุวรรณสีทองอร่าม ภายในประดิษฐานรูปหล่อสมเด็จโต พรหมรังสี', NULL, NULL, NULL, 'uploads/temple_9d5db79e117b2ea534b1e46d5e0cefa6.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (63, 'วัดเขาวงจินดาราม', 'กาญจนบุรี', NULL, 'ต.หนองโรง อ.พนมทวน จ.กาญจนบุรี', 'วัดท่ามกลางธรรมชาติขุนเขาหินปูน โดดเด่นด้วยบันไดพญานาคหลากสีทอดยาวขึ้นสู่ถ้ำเขาวง ภายในถ้ำมีหินงอกหินย้อยงดงามและประดิษฐานพระพุทธรูปปางต่างๆ', NULL, 14.3322429, 99.5122877, 'uploads/temple_db56b9c40d5d15371268bd0187442aec.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (64, 'วัดมโนธรรมาราม', 'กาญจนบุรี', NULL, 'ต.ม่วงชุม อ.ท่าม่วง จ.กาญจนบุรี', 'โบราณสถานเก่าแก่ริมแม่น้ำแม่กลอง สร้างสมัยอยุธยาตอนปลาย โดดเด่นด้วย พระปรางค์โบราณก่ออิฐถือปูน ฐานเขียงศิลาแลง และเป็นวัดที่มีบรรยากาศริมน้ำร่มรื่นสำหรับปฏิบัติธรรม', NULL, 13.9603777, 99.5988783, 'uploads/temple_d41377003b7b4f67964cc1fb9530467d.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (65, 'วัดเทวสังฆาราม (วัดเหนือ)', 'กาญจนบุรี', NULL, 'ต.บ้านเหนือ อ.เมืองกาญจนบุรี จ.กาญจนบุรี', 'พระอารามหลวงริมแม่น้ำแควใหญ่ สร้างขึ้นในสมัยรัชกาลที่ 1 เป็นวัดที่สมเด็จพระสังฆราชเจ้า กรมหลวงวชิรญาณสังวร ทรงบรรพชาเป็นสามเณรในวัยเยาว์ ภายในมีอุโบสถหลังเก่าและมณฑปประดิษฐานรอยพระพุทธบาทจำลอง', NULL, 14.026885, 99.5267243, 'uploads/temple_82ef00bdb86d84cec03992f5d287bc37.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (66, 'วัดพระแท่นดงรังวรวิหาร', 'กาญจนบุรี', NULL, 'ต.พระแท่น อ.ท่ามะกา จ.กาญจนบุรี', 'พุทธสถานศักดิ์สิทธิ์ตามคติชนชาวไทย เชื่อว่าเป็นสถานที่ปรินิพพานของพระพุทธเจ้า มีบันทึกในนิราศพระแท่นดงรังของสุนทรภู่ โดดเด่นด้วย พระแท่นบรรทมศิลาแลงโบราณ ภายในวิหารบนเนินเขา', NULL, NULL, NULL, 'uploads/temple_9c1d0a49134501d95c1048e5f851dd81.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (67, 'วัดสัตตนารถปริวัตรวรวิหาร', 'ราชบุรี', NULL, 'ต.หน้าเมือง อ.เมืองราชบุรี จ.ราชบุรี', 'เดิมตั้งอยู่บนเกาะกลางแม่น้ำแม่กลอง ก่อนรัชกาลที่ 5 โปรดฯ ให้ย้ายมาตั้งบนฝั่ง พระอุโบสถสีขาวทรงโรงล้อมรอบด้วยแนวเสาพาไลกลม ภายในประดิษฐาน "หลวงพ่อโต" พระพุทธรูปศิลาทรายแดงสมัยอยุธยา', NULL, NULL, NULL, 'uploads/temple_1a1b72b06ec0f5f32e9627158aa7d9ec.png', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (68, 'วัดมหาธาตุวรวิหาร', 'ราชบุรี', NULL, 'ต.หน้าเมือง อ.เมืองราชบุรี จ.ราชบุรี', 'โบราณสถานตั้งแต่สมัยทวารวดี โดดเด่นด้วย พระปรางค์ศิลาแลง 3 ยอด ศิลปะอยุธยาตอนต้นที่ได้รับอิทธิพลจากศิลปะลพบุรี ภายในคูหาปรางค์มีภาพจิตรกรรมสีฝุ่นรูปอดีตพุทธเจ้าที่เก่าแก่ที่สุดแห่งหนึ่งในไทย', NULL, NULL, NULL, 'uploads/temple_7110d32363b703cefd9795d240f8c8c5.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (69, 'วัดศรีสุริยวงศารามวรวิหาร', 'ราชบุรี', NULL, 'ต.หน้าเมือง อ.เมืองราชบุรี จ.ราชบุรี', 'สร้างขึ้นในปี พ.ศ. 2417 โดยสมเด็จเจ้าพระยาบรมมหาศรีสุริยวงศ์ (ช่วง บุนนาค) โดดเด่นด้วย พระอุโบสถสถาปัตยกรรมกอทิก (Gothic) หน้าต่างและซุ้มประตูโค้งแหลมเลียนแบบโบสถ์คริสต์ในยุโรป ภายในประดิษฐานพระพุทธรูปตามธรรมเนียมพุทธ', NULL, NULL, NULL, 'uploads/temple_a714626af6f96c8af8d00bb890d83076.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (70, 'วัดช่องลม', 'ราชบุรี', NULL, 'ต.หน้าเมือง อ.เมืองราชบุรี จ.ราชบุรี (และบริเวณถ้ำเขาช่องพราน อ.โพธาราม)', 'พระอารามหลวงสำคัญ ประดิษฐาน "หลวงพ่อแก่นจันทน์" พระพุทธรูปไม้จันทน์หอมศิลปะทวารวดีคู่บ้านคู่เมือง และมีจุดท่องเที่ยวธรรมชาติชมปรากฏการณ์ฝูงค้างคาวร้อยล้านบินออกจากถ้ำยามพลบค่ำ', NULL, 13.5426275, 99.8164276, 'uploads/temple_09028283fe43e9bd924e1f795f0ebca8.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (71, 'วัดมหาสมณารามราชวรวิหาร', 'เพชรบุรี', NULL, 'ต.คลองกระแชง อ.เมืองเพชรบุรี จ.เพชรบุรี', 'วัดโบราณสมัยอยุธยาเชิงเขาวัง รัชกาลที่ 4 เมื่อครั้งทรงผนวชเคยเสด็จมาจำพรรษา ภายในอุโบสถมี จิตรกรรมฝาผนังฝีมือขรัวอินโข่ง ผู้ริเริ่มนำเทคนิคทัศนียวิทยา (Perspective) แสงเงา และภาพชาวตะวันตกมาผสานกับคติธรรมพุทธศาสนา', NULL, NULL, NULL, 'uploads/temple_c213583d371eeebb559fdaf0e0449057.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (72, 'วัดคงคารามวรวิหาร', 'ราชบุรี', NULL, 'ต.คลองตาคต อ.โพธาราม จ.ราชบุรี', 'วัดมอญเก่าแก่สร้างขึ้นตั้งแต่สมัยสมเด็จพระเจ้าตากสินมหาราช โดดเด่นด้วย จิตรกรรมฝาผนังมอญอายุกว่า 250 ปี ภายในอุโบสถที่บอกเล่าทศชาติชาดกอย่างสมบูรณ์ และกุฏิเรือนไทย 9 ห้องที่เปิดเป็นพิพิธภัณฑ์พื้นบ้าน', NULL, NULL, NULL, 'uploads/temple_93784ad0d967f941bc55fad967f5d8d6.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (73, 'วัดมหาธาตุวรวิหาร', 'เพชรบุรี', NULL, 'ต.คลองกระแชง อ.เมืองเพชรบุรี จ.เพชรบุรี', 'ศูนย์กลางพุทธศาสนาเมืองเพชรบุรีตั้งแต่ยุคทวารวดี โดดเด่นด้วย พระปรางค์ 5 ยอด สีขาว สูง 55 เมตร บรรจุพระบรมสารีริกธาตุ สร้างตามคติจักรวาลวิทยา และวิหารหลวงที่มีงานปูนปั้นฝีมือช่างเมืองเพชรแท้ๆ', NULL, 13.1055042, 99.946871, 'uploads/temple_f363315ae025c363b4a33713180a2f36.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (74, 'วัดใหญ่สุวรรณารามวรวิหาร', 'เพชรบุรี', NULL, 'ต.ท่าราบ อ.เมืองเพชรบุรี จ.เพชรบุรี', 'วัดหลวงโบราณสมัยอยุธยาตอนปลาย บูรณะโดยสมเด็จพระสังฆราช (แตงโม) มี ศาลาการเปรียญไม้สักทอง ที่เคยเป็นตำหนักพระเจ้าเสือ บานประตูมี "รอยขวานพม่า" ในคราวสงคราม และจิตรกรรมฝาผนังภาพเทพชุมนุมต้นแบบสกุลช่างเพชรบุรี', NULL, 13.1085023, 99.9531234, 'uploads/temple_eb57dfa9ea46a13463e113c900c007b6.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (75, 'วัดธรรมิการามวรวิหาร', 'ประจวบคีรีขันธ์', NULL, 'ต.ประจวบคีรีขันธ์ อ.เมืองประจวบคีรีขันธ์ จ.ประจวบคีรีขันธ์', 'ตั้งอยู่บนยอดเขาช่องกระจก ต้องเดินขึ้นบันได 396 ขั้น ด้านบนประดิษฐานรอยพระพุทธบาทจำลอง พระบรมสารีริกธาตุ และต้นพระศรีมหาโพธิ์ที่ในหลวงรัชกาลที่ 9 ทรงปลูก พร้อมจุดชมทัศนียภาพ 3 อ่าว (อ่าวน้อย อ่าวประจวบฯ อ่าวมะนาว)', NULL, NULL, NULL, 'uploads/temple_8c1cc5e46b9665144019730b5431445e.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (76, 'วัดเกาะหลัก', 'ประจวบคีรีขันธ์', NULL, 'ต.ประจวบคีรีขันธ์ อ.เมืองประจวบคีรีขันธ์ จ.ประจวบคีรีขันธ์', 'พระอารามหลวงแห่งแรกของประจวบคีรีขันธ์ ก่อตั้งราว พ.ศ. 2300 ริมอ่าวประจวบฯ มีประวัติศาสตร์เกี่ยวเนื่องกับการเสด็จประพาสของพระมหากษัตริย์หลายรัชกาล และเป็นสำนักของพระครูสุทธาคมกล่อม (หลวงพ่อเปี่ยม) เกจิดังในอดีต', NULL, 11.7979654, 99.7978574, 'uploads/temple_7d94ccd5ad6aa9631b9a103a93ff3b21.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (77, 'วัดคลองวาฬ', 'ประจวบคีรีขันธ์', NULL, 'ต.คลองวาฬ อ.เมืองประจวบคีรีขันธ์ จ.ประจวบคีรีขันธ์', 'พระอารามหลวงเก่าแก่สมัยอยุธยาตอนปลาย โดดเด่นด้วย พระอุโบสถไม้สักทองทั้งหลัง สลักเสลาลวดลายไทยประเพณี หน้าบันและเพดานประดับมุกอย่างวิจิตรบรรจงริมอ่าวคลองวาฬ', NULL, NULL, NULL, 'uploads/temple_2e1b8153ad3a5cc3c621087b9f685215.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (78, 'วัดเขาโบสถ์', 'ประจวบคีรีขันธ์', NULL, 'ต.กำเนิดนพคุณ อ.บางสะพาน จ.ประจวบคีรีขันธ์', 'ริเริ่มสร้างโดยหลวงพ่อท้วม เกจิดังแห่งบางสะพาน ตัวพระอุโบสถตั้งอยู่บนยอดเขาสูง เป็นจุดชมทิวทัศน์เมืองบางสะพานและแนวชายทะเลแบบพาโนรามา ทั้งยังเป็นที่เคารพสักการะสรีรสังขารหลวงพ่อท้วม', NULL, NULL, NULL, 'uploads/temple_8f440e52719920b4690af5f0fc1e4b05.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (79, 'วัดกุยบุรี', 'ประจวบคีรีขันธ์', NULL, 'ต.กุยบุรี อ.กุยบุรี จ.ประจวบคีรีขันธ์', 'วัดเก่าแก่อายุกว่า 300 ปี สมัยอยุธยาตอนปลาย ประดิษฐานพระธาตุกุยบุรี และรูปหล่อปิดทองของ "หลวงพ่อในกุฏิ" (พระครูสิงหคุณากร) พระเกจิวิปัสสนาจารย์ที่ชาวบ้านยกย่องเป็นเทพเจ้าแห่งกุยบุรี', NULL, 12.0668556, 99.8581359, 'uploads/temple_d3f7c237eccef9362b498dcf58ca9921.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
INSERT INTO temples (id, name, province, district, address, description, tags, latitude, longitude, image, promptpay_id, badge, created_at) VALUES (80, 'วัดเขากระโหลก', 'ประจวบคีรีขันธ์', NULL, 'ต.ปากน้ำปราณ อ.ปราณบุรี จ.ประจวบคีรีขันธ์', 'พระอุโบสถสีทองอร่ามตกแต่งลวดลายปูนปั้นประณีต ตั้งตระหง่านอยู่ด้านหน้าภูเขาหินปูนริมหาดเขากะโหลก มีตำนานความเชื่อเรื่อง "จระเข้จักรพรรดิ" หรือพญาจระเข้เฝ้าสมบัติ ผู้คนนิยมเดินทางมาขอพรเรื่องโชคลาภและการงาน', NULL, NULL, NULL, 'uploads/temple_6c5b7d65a5f4106033765cb9de04abfb.jpg', NULL, 'แนะนำ', '2026-10-09 16:22:40') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, province = EXCLUDED.province, district = EXCLUDED.district, address = EXCLUDED.address, description = EXCLUDED.description, tags = EXCLUDED.tags, latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, image = EXCLUDED.image, promptpay_id = EXCLUDED.promptpay_id, badge = EXCLUDED.badge;
