INSERT INTO news (id, temple_id, title, content, image, created_at) VALUES (2, 1, 'วัดพระเชตุพนวิมลมังคลาราม (วัดโพธิ์) จัดงานบุญเดือนสาม', 'วัดพระเชตุพนวิมลมังคลาราม (วัดโพธิ์) ได้มีการจัดงานบุญเดือนสาม ประจำปี 2569 เริ่ม 28 กุมภาพันธ์ ถึง 9 มีนาคม เชิญชวนพ่อแม่พี่น้องเข้าร่วมงานบุญ เพื่อความเป้นสิริมงคล', 'news_6ad1e011cdad3.png', '2026-10-16 15:28:01') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, image = EXCLUDED.image;
